-- 兼容 MySQL 8.0+ / TiDB

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `session_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `src_ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  `src_port` int NOT NULL,
  `dst_ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dst_port` int NOT NULL,
  `protocol` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `app_protocol` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `direction` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `start_time` timestamp NOT NULL,
  `duration` int NOT NULL DEFAULT '0',
  `up_packets` int NOT NULL DEFAULT '0',
  `down_packets` int NOT NULL DEFAULT '0',
  `up_bytes` bigint NOT NULL DEFAULT '0',
  `down_bytes` bigint NOT NULL DEFAULT '0',
  `dst_country` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `threat_score` int NOT NULL DEFAULT '0',
  `meta` json NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_sessions_src` (`src_ip`),
  KEY `idx_sessions_dst` (`dst_ip`),
  KEY `idx_sessions_start` (`start_time`),
  KEY `idx_sessions_app` (`app_protocol`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=90001;


DROP TABLE IF EXISTS `analysis_runs`;
CREATE TABLE `analysis_runs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `rule_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'running',
  `sessions_scanned` int NOT NULL DEFAULT '0',
  `alerts_generated` int NOT NULL DEFAULT '0',
  `duration_ms` int NOT NULL DEFAULT '0',
  `started_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `finished_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=2256383;


DROP TABLE IF EXISTS `alerts`;
CREATE TABLE `alerts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `rule_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rule_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `src_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dst_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `score` int NOT NULL DEFAULT '0',
  `evidence` json NOT NULL,
  `related_sessions` json NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `run_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_alerts_rule` (`rule_code`),
  KEY `idx_alerts_sev` (`severity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=120001;


DROP TABLE IF EXISTS `ingest_batches`;
CREATE TABLE `ingest_batches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `filename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `size_bytes` bigint NOT NULL DEFAULT '0',
  `packets` int NOT NULL DEFAULT '0',
  `flows` int NOT NULL DEFAULT '0',
  `skipped` int NOT NULL DEFAULT '0',
  `duration_ms` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `id` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=2030001;


DROP TABLE IF EXISTS `custom_models`;
CREATE TABLE `custom_models` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `severity` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `dimensions` json NOT NULL,
  `metrics` json NOT NULL,
  `filters` json NOT NULL,
  `having_def` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=60001;


SET FOREIGN_KEY_CHECKS = 1;
